WITH FilteredSuppliers AS (SELECT * FROM suppliers WHERE supplier_name IS NULL OR country <> 'JP'), agg AS (SELECT CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, ROUND((100 * SUM(CASE WHEN country = 'SG' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_sg FROM FilteredSuppliers GROUP BY CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.8 THEN 'mid' ELSE 'low' END) SELECT rating_bucket, city_values, pct_sg FROM agg WHERE pct_sg >= 79 ORDER BY pct_sg DESC, rating_bucket LIMIT 3;
